    gaD3DPerspectiveVertices[1].fY = 0.0;
    gaD3DPerspectiveVertices[1].fU = 0.0;
    gaD3DPerspectiveVertices[2].fX = 0.0;
    gaD3DPerspectiveVertices[2].fY = 0.0;
    gaD3DPerspectiveVertices[3].fX = 0.0;
    gaD3DPerspectiveVertices[3].fY = 0.0;
    gaD3DPerspectiveVertices[3].fV = 0.0;
