      pWallCornerFixup[-1] <<= 0x10;
      pWallCornerFixup[-3] <<= 0x10;
      *pWallCornerFixup <<= 0x10;
      pWallCornerFixup[2] <<= 0x10;
      pWallCornerFixup[3] <<= 0x10;
      pWallCornerFixup[5] <<= 0x10;
      pWallCornerFixup[6] <<= 0x10;
      pWallCornerFixup[8] <<= 0x10;
      pWallCornerFixup[9] <<= 0x10;
