    gaD3DSmackerVertices[1].fZ = 0.5;
    gaD3DSmackerVertices[1].fRHW = 1.0;
    gaD3DSmackerVertices[1].fV = 1.0;
    gaD3DSmackerVertices[1].fU = 0.0;
    gaD3DSmackerVertices[2].fX = (float)(nSurfaceX + 0x100);
